import { forwardRef, useMemo, Children, isValidElement } from "react";
import { AreaChart as RechartsAreaChart, ResponsiveContainer } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { ChartClasses, StyledChart } from "./chart.styles";
import { ChartContext } from "./hooks/use-chart";
import { useAreaChart } from "./hooks/use-area-chart";
import { AreaChartProps } from "./chart.types";
const AreaChart = forwardRef<HTMLDivElement, AreaChartProps>(
  (
    {
      data: initialData,
      children,
      className,
      style,
      styleSlots,
      variant = "default",
      type = "default",
      margin: marginProp,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const { chartData, numCategoricalColors, numAreas, childrenWithProps, gradientDefs, colorMap } =
      useAreaChart({
        data: initialData,
        children,
        type,
      });

    // Calculate smart default margins based on child components
    const defaultMargin = useMemo(() => {
      const hasReferenceLine = Children.toArray(children).some(
        (child) =>
          isValidElement(child) &&
          (child.type as { displayName?: string })?.displayName === "ReferenceLine",
      );

      return {
        top: 10,
        right: hasReferenceLine ? 60 : 10,
        left: 10,
        bottom: 10,
      };
    }, [children]);

    const margin = { ...defaultMargin, ...marginProp };

    return (
      <ChartContext.Provider
        value={{
          data: initialData,
          chartData,
          type,
          numCategoricalColors,
          numAreas,
          colorMap,
        }}
      >
        <StyledChart
          ref={ref}
          className={clsx(ChartClasses.root, className)}
          currentTheme={theme}
          style={{ width: "100%", height: "100%", ...style }}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          <ResponsiveContainer
            className={ChartClasses.responsiveContainer}
            height="100%"
            width="100%"
          >
            <RechartsAreaChart className={ChartClasses.areaChart} data={chartData} margin={margin}>
              {gradientDefs && gradientDefs.length > 0 && <defs>{gradientDefs}</defs>}
              {childrenWithProps}
            </RechartsAreaChart>
          </ResponsiveContainer>
        </StyledChart>
      </ChartContext.Provider>
    );
  },
);

AreaChart.displayName = "AreaChart";

export default AreaChart;
